<?php require_once 'includes/auth.php';if(customer_logged_in()){header('Location: account.php');exit;}$e='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=db()->prepare('SELECT * FROM customers WHERE email=?');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){$_SESSION['customer_id']=$u['id'];$r=$_POST['redirect']??'account.php';if(!preg_match('/^[A-Za-z0-9_.-]+\.php$/',$r))$r='account.php';header('Location: '.$r);exit;}$e='Invalid email or password.';}$title='Customer Login - '.APP_NAME;include 'includes/header.php';?><h1>Customer Login</h1><form class="form" method="post"><?php if($e):?><div class="notice error"><?=htmlspecialchars($e)?></div><?php endif;?><input type="hidden" name="redirect" value="<?=htmlspecialchars($_GET['redirect']??'account.php')?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Login</button><p>No account? <a href="register.php">Register</a></p></form><?php include 'includes/footer.php';?>